import { themes, tokenNames } from '@surfnet/curve-tokens';
// Ordered groups. The first group whose `match` returns true claims the token, so
// the more specific prefixes come before the catch-all colour group at the end.
export const TOKEN_GROUPS = [
    {
        id: 'font-family',
        title: 'Font families',
        description: 'Typeface stacks used across the system.',
        kind: 'font-family',
        match: (n) => n === 'font-sans' || n === 'font-mono',
    },
    {
        id: 'font-weight',
        title: 'Font weights',
        description: 'Numeric weight steps for the type scale.',
        kind: 'font-weight',
        match: (n) => n.startsWith('font-weight-'),
    },
    {
        id: 'typography',
        title: 'Typography',
        description: 'Font-size / line-height pairs of the type scale.',
        kind: 'font-size',
        match: (n) => n.startsWith('text-'),
    },
    {
        id: 'radius',
        title: 'Radius',
        description: 'Corner radii from extra-small to fully rounded.',
        kind: 'radius',
        match: (n) => n.startsWith('radius-'),
    },
    {
        id: 'container',
        title: 'Container widths',
        description: 'Named max-width container sizes.',
        kind: 'raw',
        match: (n) => n.startsWith('container-'),
    },
    {
        id: 'breakpoint',
        title: 'Breakpoints',
        description: 'Responsive breakpoint widths.',
        kind: 'raw',
        match: (n) => n.startsWith('breakpoint-'),
    },
    {
        id: 'shadow',
        title: 'Shadows',
        description: 'Box / inset / drop shadow primitives, broken down into their offset, blur and spread parts.',
        kind: 'raw',
        match: (n) => n.startsWith('shadow-') || n.startsWith('inset-shadow-') || n.startsWith('drop-shadow-'),
    },
    {
        id: 'blur',
        title: 'Blur',
        description: 'Blur radii for backdrop / filter effects.',
        kind: 'raw',
        match: (n) => n.startsWith('blur-'),
    },
    {
        id: 'chart',
        title: 'Chart colours',
        description: 'Categorical palette for data visualisations.',
        kind: 'color',
        match: (n) => n.startsWith('chart-'),
    },
    {
        id: 'sidebar',
        title: 'Sidebar colours',
        description: 'Colours scoped to the sidebar surface.',
        kind: 'color',
        match: (n) => n.startsWith('sidebar-'),
    },
    {
        id: 'alpha',
        title: 'Alpha',
        description: 'Translucent overlay steps.',
        kind: 'color',
        match: (n) => n.startsWith('alpha-'),
    },
    {
        id: 'custom',
        title: 'Internal / custom',
        description: 'Lower-level tokens used internally for per-component dark-mode overrides. Rarely referenced directly.',
        kind: 'color',
        match: (n) => n.startsWith('custom-'),
    },
    {
        id: 'semantic',
        title: 'Semantic colours',
        description: 'The core role-based colours (background, foreground, primary, border, …) you reach for first.',
        kind: 'color',
        // Catch-all: any token not claimed above is a semantic colour.
        match: () => true,
    },
];
/**
 * Bucket every shipped token into its group, preserving token order within each
 * group. Empty groups are dropped.
 */
export function getTokenGroups() {
    const buckets = new Map(TOKEN_GROUPS.map((g) => [g.id, []]));
    for (const name of tokenNames) {
        const group = TOKEN_GROUPS.find((g) => g.match(name));
        if (group)
            buckets.get(group.id).push({ name, cssVar: `var(--${name})` });
    }
    return TOKEN_GROUPS.map((group) => ({ group, tokens: buckets.get(group.id) })).filter(({ tokens }) => tokens.length > 0);
}
/**
 * Pair the split `text-<size>-font-size` / `text-<size>-line-height` tokens back
 * into a single scale entry per size, in shipped order.
 */
export function getTypographyScale() {
    return tokenNames
        .filter((n) => n.startsWith('text-') && n.endsWith('-font-size'))
        .map((fontSizeName) => {
        const id = fontSizeName.replace(/-font-size$/, '');
        return { id, fontSizeName, lineHeightName: `${id}-line-height` };
    });
}
/**
 * Resolve a token's value for a given theme/mode straight from the token map
 * shipped by `@surfnet/curve-tokens`. The map is fully resolved (every theme/mode holds
 * all tokens with the cascade already baked in), so this is a plain lookup — no
 * DOM, no `getComputedStyle`. Unknown theme/mode fall back to `default` / `light`.
 */
export function getTokenValue(theme, mode, name) {
    const byMode = themes[theme] ?? themes.default;
    const values = byMode[mode] ?? byMode.light;
    return values[name] ?? '';
}
